import assert from 'node:assert/strict';
import test from 'node:test';

// Independent finite relational examples, not output generated by a lowerer.
// Endpoints are already valid; runtime endpoint/key validation is still required.
const left = [{id: 1, time: 5}, {id: 2, time: 20}];
const right = [{id: 1, start: 0, end: 10}, {id: 3, start: 2, end: 8}];
function pointJoin(kind, correlate) {
  const result = [];
  for (const l of left) {
    const matches = right.filter(r => (!correlate || l.id === r.id) && r.start <= l.time && l.time < r.end);
    if (kind === 'semi' || kind === 'anti') {
      if ((matches.length > 0) === (kind === 'semi')) result.push([l.id]);
    } else if (matches.length) {
      for (const r of matches) result.push([l.id, r.id]);
    } else if (kind === 'left') result.push([l.id, null]);
  }
  return result;
}
const unique = tuples => new Set(tuples.map(x => JSON.stringify(x))).size === tuples.length;
test('temporal pairs distinguish matches and a single unmatched left occurrence', () => {
  assert.deepEqual(pointJoin('inner', false), [[1,1],[1,3]]);
  const result = pointJoin('left', false);
  assert.deepEqual(result, [[1,1],[1,3],[2,null]]);
  assert.ok(unique(result));
  assert.ok(!unique(result.map(([l]) => [l])));
  assert.ok(result.some(([,r]) => r === null));
  // Removing the right component loses the pair witness, despite unchanged types.
});
test('equality coverage permits an independent left key without invalidating pairs', () => {
  const result = pointJoin('left', true);
  assert.deepEqual(result, [[1,1],[2,null]]);
  assert.ok(unique(result));
  assert.ok(unique(result.map(([l]) => [l])));
});
test('semi and anti retain left identity without requiring right output keys', () => {
  assert.deepEqual(pointJoin('semi', false), [[1]]);
  assert.deepEqual(pointJoin('anti', false), [[2]]);
});
